import{_ as s,l as o,o as t,c as n,v as e,p as h,x as r,d as m,i as d,S as l}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Girsanov 测度变换","description":"","frontmatter":{"title":"Girsanov 测度变换","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/girsanov-measure.md","filePath":"quant/girsanov-measure.md","lastUpdated":1789023840000}'),p={name:"quant/girsanov-measure.md"};function _(u,a,E,c,v,A){const i=o("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="girsanov-测度变换" tabindex="-1">Girsanov 测度变换 <a class="header-anchor" href="#girsanov-测度变换" aria-label="Permalink to &quot;Girsanov 测度变换&quot;">​</a></h1><div class="epigraph"><p>Girsanov 用指数鞅改布朗的漂移：在 $Q$ 下，$W^Q_t=W_t+\\int_0^t\\theta_s\\,\\mathrm d s$ 仍是布朗运动。</p><footer>—— 据 Girsanov, Theory of Probability and Its Applications, 1960；Karatzas and Shreve, 1991, §3.5；Shreve, Stochastic Calculus for Finance II, 第 5 章整理</footer></div><p>上一课<a href="/quant/radon-nikodym">Radon–Nikodym 导数</a>给出抽象密度 \\(\\xi\\)。缺口是布朗运动上的具体形状：要让 \\(\\mathrm d S=\\mu S\\,\\mathrm d t+\\sigma S\\,\\mathrm d W\\) 在新测度下变成 \\(\\mathrm d S=r S\\,\\mathrm d t+\\sigma S\\,\\mathrm d W^Q\\)，密度必须把漂移移动 \\(\\theta=(\\mu-r)/\\sigma\\)。本课只给出这条变换，并留下 Novikov 条件；「为何选这个 \\(\\theta\\)」是下一课风险中性的经济内容。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RN 密度可以是任意正鞅。对布朗信息流，连续正鞅由随机指数给出。缺口是：选定过程 \\(\\theta\\)，令</p> \\[\\xi_t=\\exp\\Bigl(-\\int_0^t\\theta_s\\,\\mathrm d W_s-\\tfrac12\\int_0^t\\theta_s^2\\,\\mathrm d s\\Bigr), \\]<p>在 \\(\\xi\\) 为鞅时定义 \\(Q\\)，证明 \\(W^Q=W+\\int\\theta\\) 在 \\(Q\\) 下是标准布朗。没有这条，换测度只改期望权重，不改路径的漂移语言。</p><p>\\(\\theta\\) 叫市场的风险的市场价格（下一课才命名）。本课只把它当作漂移平移的旋钮。</p><h3 id="girsanov-不改变波动率" tabindex="-1">Girsanov 不改变波动率 <a class="header-anchor" href="#girsanov-不改变波动率" aria-label="Permalink to &quot;Girsanov 不改变波动率&quot;">​</a></h3><p>二次变差是路径性质，\\([W]_t=t\\) 在等价测度下不变。因此 \\(\\sigma\\) 不随 \\(P\\to Q\\) 改变；变的只是 \\(\\mathrm d t\\) 项。把「风险中性」理解成「波动率换成别的数」，是把测度和模型校准混在一起。校准是<a href="/quant/vol-as-input">波动率是输入不是输出</a>的事。</p><p><span class="marginnote">Novikov：\\(\\mathbb E\\exp(\\tfrac12\\int\\theta^2)\\lt \\infty\\) 则指数局部鞅是真鞅。实践中常对有界 \\(\\theta\\) 直接用；无界时要核验，否则 \\(Q\\) 甚至不是概率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设 \\(\\theta\\) 适应、\\(\\int_0^T\\theta^2\\lt \\infty\\) a.s.，且 \\(\\xi\\) 为 \\(P\\)-鞅。定义 \\(Q(A)=\\mathbb E_P[\\xi_T 1_A]\\)。则 \\(W^Q_t=W_t+\\int_0^t\\theta_s\\,\\mathrm d s\\) 是 \\(Q\\)-布朗运动（至 \\(T\\)）。SDE \\(\\mathrm d X=\\mu\\,\\mathrm d t+\\sigma\\,\\mathrm d W\\) 改写为 \\(\\mathrm d X=(\\mu-\\sigma\\theta)\\,\\mathrm d t+\\sigma\\,\\mathrm d W^Q\\)。多维时 \\(\\theta\\) 是向量，\\(\\sigma\\theta\\) 是矩阵乘积；\\(\\sigma\\) 不满秩时不是任意漂移都能消掉——那是不全市场课的缺口。</p><p>Itô 公式在 \\(Q\\) 下对 \\(W^Q\\) 照常使用，因为 \\(W^Q\\) 仍是布朗。密度过程满足 \\(\\mathrm d\\xi=-\\theta\\xi\\,\\mathrm d W\\)，无漂移，与上一课「密度是 \\(P\\)-鞅」一致。</p>',14)),(t(),h(l,null,{default:r(()=>[d(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20THETA%5B%22%E8%BF%87%E7%A8%8B%20theta%22%5D%20--%3E%20XI%5B%22%E6%8C%87%E6%95%B0%E5%AF%86%E5%BA%A6%22%5D%0A%20%20XI%20--%3E%20Q%5B%22%E7%AD%89%E4%BB%B7%E6%B5%8B%E5%BA%A6%20Q%22%5D%0A%20%20Q%20--%3E%20WQ%5B%22W%20%E5%8A%A0%E7%A7%AF%E5%88%86%20theta%20%E6%98%AF%20Q%20%E5%B8%83%E6%9C%97%22%5D%0A%20%20WQ%20--%3E%20DRIFT%5B%22%E6%BC%82%E7%A7%BB%E5%B9%B3%E7%A7%BB%20sigma%20theta%22%5D%0A%20%20DRIFT%20--%3E%20RN%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E9%A3%8E%E9%99%A9%E4%B8%AD%E6%80%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指数里的 \\(-\\tfrac12\\int\\theta^2\\) 又是 Itô 修正：\\(\\mathrm e^{-\\int\\theta\\,\\mathrm d W}\\) 单独不是鞅。Girsanov 的核心计算是：把 \\(W^Q\\) 的特征函数在 \\(Q\\) 下用 \\(\\xi\\) 写回 \\(P\\)，认出独立高斯增量。直观上，乘 \\(\\xi\\) 给那些沿 \\(\\theta\\) 方向走得更远的路径更大权重，等效于把均值平移。</p><p>波动率矩阵决定能平移的漂移子空间。\\(\\theta\\) 的个数不能超过独立布朗的个数——市场有多少噪声源，就能对冲多少风险溢价。本课只把线性代数接口留下。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Girsanov–Meyer 对半鞅的一般形式，不讨论无穷时间区间上的一致性。跳过程的 Esscher 变换是另一套密度，留给跳课预览。后课默认：改布朗漂移 = 选 \\(\\theta\\) 做指数鞅；\\(\\sigma\\) 不变。下一课<a href="/quant/risk-neutral-measure">风险中性测度</a>把 \\(\\theta\\) 选成使贴现标的为鞅的那个。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Girsanov 用指数鞅平移布朗漂移，\\(W^Q=W+\\int\\theta\\)。</li><li>波动率（二次变差）在等价测度下不变。</li><li>Novikov 把指数局部鞅升级为密度。</li><li>\\(\\mu\\mapsto\\mu-\\sigma\\theta\\) 是 SDE 在 \\(Q\\) 下的全部变化。</li><li>出处：Girsanov 1960；Karatzas–Shreve §3.5；Shreve SDE II 第 5 章。</li></ul>',7))])}const g=s(p,[["render",_]]);export{f as __pageData,g as default};
